var a=[{title:`Ruchy biodra`,text:`Zgięcie w biodrze przybliża udo do tułowia, a wyprost odwodzi je do tyłu. Staw rotuje też do wewnątrz i na zewnątrz oraz przemieszcza nogę w poprzek ciała lub od niego. Codzienne ruchy łączą kilka kierunków, więc skłon do palców mówi tylko o części historii.`},{title:`Ćwiczenia do wypróbowania`,text:`Wygodne rozciąganie zginaczy bioder w klęku podpartym bada wyprost, gdy utrzymujesz kontrolę miednicy. Delikatne rotacje bioder 90/90 lub ćwiczenia rotacji w siadzie ćwiczą rotację, a boczny wykrok z podparciem bada długość i kontrolę mięśni przywodzicieli (wewnętrzna strona uda). Zacznij powoli i trzymaj się podpory, jeśli równowaga wydaje się chwiejna.`},{title:`Biodra w Twoich ćwiczeniach`,text:`Przysiady wymagają, by biodra i kostki poruszały się razem. Zawiasy wymagają zgięcia w biodrach przy kontrolowanym tułowiu. W przysiadzie ze statycznym rozkrokiem jedno biodro się prostuje, a drugie zgina. Jeśli głęboki przysiad jest niekomfortowy, inne ustawienie stóp, mniejsza głębokość, podparcie pięt lub przysiad do krzesła mogą pomóc szybciej niż wymuszanie rozciągnięcia.`},{title:`Biodra każdego są inne`,text:`Kształt panewki, historia treningowa, obecna siła i tolerancja stawu wpływają na Twój zakres. Asymetria nie jest automatycznie wadą, a to samo rozciąganie nie należy do każdego planu. Przerwij każde ćwiczenie, które powoduje uczucie uszczypnięcia, ostry ból stawu lub objawy, które się utrzymują, i w razie potrzeby zgłoś się do lekarza lub fizjoterapeuty.`},{title:`Śledzenie postępów`,text:`Wykonaj kilka skupionych ćwiczeń bioder przed treningami, w których ruch na tym korzysta. Mierz postęp tym, jak pewne i płynne wydają się Twoje przysiady, zawiasy i wykroki, a maksymalną głębokość rozciągania odłóż na bok.`}];var o=[{label:`ACE 2026: ruchomość a elastyczność`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`Biblioteka ćwiczeń ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:a,sources:o};export{r as default,a as sections,o as sources};